    const subs = old ? Object.values(S.all('clss')).filter(x => x.asg === old.id) : [];
    if (old && subs.length && (old.kind !== a.kind || (a.kind === 'quiz' && JSON.stringify(old.quiz) !== JSON.stringify(a.quiz)))) fail('LOCKED', 'The questions cannot be changed after students have answered.', 409);
