    let sess = ''; if (kind === 'chat') { const d = S.get('clsh', String(b.sess || '')); if (!d || d.courseId !== c.id || !(d.status === 'live' || (d.status === 'ended' && now() - d.endedAt < 30 * 60000))) fail('CHAT_CLOSED', 'Chat is open only during the live session.', 409); sess = d.id; }
    let parent = ''; if (kind === 'reply') { const p = S.get('clsp', String(b.parent || '')); if (!p || p.courseId !== c.id) fail('NOT_FOUND', 'Question not found', 404); parent = p.id; }
    const doc = { id: rid(8), courseId: c.id, kind, sess, parent, uid: u.id, name: u.name, role: u.role === 'student' ? 'student' : 'staff', text, at: now() }; await save('clsp', doc.id, doc);
    if (kind === 'ann') await inApp(members(c.id), bi('Announcement: ', 'Annonce : ') + c.code, text.slice(0, 120)); return { ok: true, id: doc.id };
