  /* ---- CSV exports for the lecturer: grades and online attendance ---- */
  const csvCell = v => { let s = String(v == null ? '' : v); if (/^[=+\-@\t\r]/.test(s)) s = "'" + s; return /[",\n\r]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; };
  function exportCsv(u, courseId, kind) {
    const c = course(courseId); if (!c || !(teaches(u, c) || isMgr(u))) fail('FORBIDDEN', 'Not allowed', 403); const ay = logic.AY();
    const stu = Object.values(S.all('enroll')).filter(e => e.courseId === c.id && (!e.ay || e.ay === ay)).map(e => S.get('students', e.matric) || Object.values(S.all('students')).find(s => s.matric === e.matric) || { matric: e.matric, name: e.matric, userId: '' }).sort((a, b) => String(a.name).localeCompare(String(b.name)));
    let head, rows;
    if (kind === 'attendance') { const ss = Object.values(S.all('clsh')).filter(s => s.courseId === c.id && ['live', 'ended'].includes(s.status)).sort((a, b) => a.start - b.start); head = ['Matricule', 'Name'].concat(ss.map(s => new Date(s.start + 3600e3).toISOString().slice(0, 10) + ' ' + s.title), ['Sessions joined', 'Of']); rows = stu.map(s => { const j = ss.map(x => S.get('clsr', x.id + '_' + s.userId) ? 'Yes' : 'No'); return [s.matric, s.name].concat(j, [j.filter(v => v === 'Yes').length, ss.length]); }); }
    else { const as = Object.values(S.all('clsa')).filter(a => a.courseId === c.id && a.status === 'published').sort((a, b) => a.at - b.at), tot = as.reduce((s, a) => s + a.points, 0); head = ['Matricule', 'Name'].concat(as.map(a => a.title + ' (/' + a.points + ')'), ['Total', 'Out of']); rows = stu.map(s => { const sc = as.map(a => { const x = S.get('clss', a.id + '_' + s.userId); return x && x.status === 'graded' ? x.score : ''; }); return [s.matric, s.name].concat(sc, [sc.reduce((q, v) => q + (v === '' ? 0 : v), 0), tot]); }); }
    return '\ufeff' + [head].concat(rows).map(r => r.map(csvCell).join(',')).join('\r\n') + '\r\n';
  }

  /* ---- AI drafting: slides, handouts, quizzes and assignments, aligned with the course's APPROVED plan ---- */
