    return { apps: apps.length, byStage: by(apps, 'stage'), byCat: by(apps, 'cat'), partners: prt.length, pByStage: by(prt, 'stage'), vacancies: Object.values(S.all('hrv')).filter(v => v.status === 'published').length, eeo: apps.reduce((o, a) => { if (a.eeo) o[a.eeo] = (o[a.eeo] || 0) + 1; return o; }, {}), overdue: overdue().length, retentionMonths: cfg().retentionMonths };
